\u0055\u003f\u0020\u0071\u002c\u0060\u002d\u0072\u0026\u0077\u003a\u005f\u006c\u007d\u0035\u006b\u0066\u002c\u005f\u0066\u0051\u003d\u0072\u0061\u007b\u0030\u0078\u003f\u006c\u0065\u0039\u007e\u007b\u003d\u0074\u0034\u002c\u0059\u0055\u005f\u0070\u0077\u003c\u0077\u0073\u003f\u0070\u0041\u0079\u007c\u0023\u0023\u0020\u0029\u005b\u0023\u0021\u0025\u0068\u0035\u0059\u0067\u0021\u0036\u0054\u0025\u007d\u0074\u006e\u0071\u0058\u003c\u0043\u0043\u0026\u002a\u002f\u003d\u002d\u002e\u0037\u004e\u0040\u004f\u006f\u0027\u0068\u0077\u0053\u0060\u005f\u005e\u0073\u0028\u0069\u003e\u0026\u006d\u0048\u0052\u0048\u003c\u0047\u0023\u0067\u005c\u004d\u0044\u004e\u0031\u006e\u0028\u002b\u005b\u0075\u0024\u0068\u0064\u006c\u006f\u006f\u0035\u0046\u007a\u0028\u006b\u0062\u0026\u007a\u0077\u0027\u0056\u002e\u0040\u0073\u003e\u003b\u004e\u007c\u0023\u0050\u0031\u0064\u005c\u0058\u004b\u0054\u005f\u002a\u0027\u0042\u004b\u0057\u0056\u005a\u0068\u0031\u0022\u0040\u0039\u007e\u0038\u007e\u0078\u0074\u004b\u0053\u0026\u003d\u0029\u0036\u002c\u0058\u0024\u004f\u003d\u0073\u0072\u006a\u0069\u0023\u0044\u0044\u005e\u0022\u0021\u002a\u0028\u002d\u0021\u0027\u0055\u0026\u0043\u0066\u0058\u0055\u0034\u0063\u0034\u006d\u0079\u004b\u0070\u003d\u0064\u0060\u007c\u004f\u006f\u0067\u0029\u0070\u004f\u003e\u004b\u007b\u007a\u005a\u0033\u0060\u0029\u0036\u0051\u006a\u007e\u005b\u006f\u0027\u0057\u0037\u007e\u007c\u0037\u0041\u0074\u0035\u0072\u0034\u003c\u0053\u0068\u0069\u005d\u002d\u0069\u003a\u0024\u0064\u0052\u0032\u0049\u0030\u0079\u005e\u0024\u0031\u0037\u006c\u005b\u0025\u0047\u0068\u006c\u0065\u0053\u0063\u005d\u0078\u003d\u006c\u005a\u003b\u0039\u0035\u0075\u006c\u0029\u0026\u0043\u0030\u0044\u0053\u0043\u0044\u0035\u0039\u004e\u0023\u002c\u0061\u0024\u003b\u003e\u0026\u0038\u0034\u0078\u0069\u0064\u006b\u005a\u0023\u0030\u0023\u005c\u0048\u0052\u0074\u0070\u0024\u0033\u0070\u006d\u0028\u002a\u005e\u0025\u005c\u0050\u004c\u0051\u0029\u0065\u0065\u004f\u0036\u0063\u0075\u0057\u005f\u0064\u0042\u005b\u0048\u0079\u0041\u003f\u0070\u0079\u0025\u0055\u0076\u006d\u0042\u0022\u0050\u0042\u0039\u0047\u0065\u0078\u003e\u005a\u0031\u0069\u0039\u002e\u007c\u0040\u003a\u007c\u0072\u002e\u005e\u0025\u005d\u0032\u002d\u0038\u007d\u007c\u0023\u0065\u0054\u0061\u0072\u0062\u006b\u0049\u0027\u0057\u007e\u0051\u0049\u0066\u005d\u0069\u004f\u0037\u0025\u005a\u0023\u0031\u0023\u0053\u0021\u0073\u0037\u002f\u0033\u005b\u002f\u0074\u0053\u0036\u0037\u0029\u0044\u0034\u0068\u0052\u0033\u003d\u004f\u0054\u0071\u0073\u0033\u0023\u004d\u003d\u0049\u0079\u002c\u0029\u002b\u0079\u005a\u0060\u007d\u0067\u0034\u0063\u004d\u0032\u0051\u0059\u0055\u0075\u006f\u0023\u0042\u0069\u0071\u003b\u004d\u0022\u0040\u0040\u0042\u0030\u003d\u0046\u0057\u0039\u004f\u0039\u004f\u006b\u0043\u0035\u0030\u0059\u0026\u006f\u0073\u0035\u0050\u0045\u003a\u0029\u002e\u003b\u002a\u003f\u0076\u0028\u0044\u002a\u0034\u0051\u0073\u0040\u0058\u0075\u004d\u0035\u003d\u006c\u0047\u0064\u006e\u0066\u0021\u0025\u0026\u0027\u0064\u005d\u0052\u0059\u0028\u0055\u0046\u006d\u0057\u0069\u0044\u004c\u0031\u0045\u0054\u0048\u0023\u0025\u004b\u007a\u006a\u0059\u002e\u0079\u0026\u006a\u007d\u0069\u007a\u005f\u006e\u0067\u004b\u003d\u0058\u0045\u0053\u0034\u0050\u005a\u0057\u007b\u0061\u0070\u0038\u0069\u0026\u0076\u0051\u003d\u0074\u0079\u004c\u0048\u0033\u004f\u004d\u003f\u0020\u003e\u002e\u0025\u0035\u006e\u004b\u0051\u0079\u003b\u0070\u0047\u0063\u0039\u0033\u0024\u007d\u0058\u0030\u0033\u0039\u0052\u004f\u002e\u005b\u0049\u003c\u004a\u0064\u0059\u003c\u002b\u006a\u0074\u0069\u006c\u004e\u006f\u0067\u006b\u0024\u007d\u0058\u0057\u004e\u002d\u0024\u0021\u0031\u006c\u002e\u0045\u0033\u0067\u0066\u003d\u0038\u0039\u003f\u0071\u0049\u005c\u0024\u0045\u005f\u0057\u003e\u0073\u007b\u0043\u0063\u002c\u0020\u0029\u005e\u005f\u0040\u006c\u0071\u0062\u0029\u0040\u0058\u003e\u003d\u0072\u0051\u005e\u0026\u0055\u0035\u0043\u0052\u0026\u0062\u0037\u004d\u0039\u0061\u0057\u0045\u0022\u0041\u007d\u005d\u005e\u0069\u0078\u0030\u0051\u0079\u003e\u0024\u0051\u0070\u0060\u0036\u0055\u0037\u006c\u0066\u004d\u0065\u005a\u004a\u0055\u006d\u0032\u0074\u002d\u005d\u0061\u005c\u002d\u0066\u003c\u0077\u006c\u0039\u004f\u0038\u0024\u006d\u0033\u0076\u006f\u004e\u0033\u0021\u0061\u0067\u0031\u0043\u0036\u0023\u0023\u005c\u007d\u0043\u003b\u0077\u006b\u005d\u0077\u006b\u0066\u0022\u0074\u004d\u0078\u0053\u0044\u005b\u003a\u004e\u004c\u0037\u0037\u0066\u0036\u002e\u006f\u0058\u0047\u0034\u0079\u0029\u0043\u0067\u005e\u007b\u0077\u0078\u0035\u0029\u0078\u0068\u002b\u0036\u005c\u005a\u006c\u0071\u0065\u0064\u003a\u0047\u0056\u0061\u0029\u0067\u0054\u005d\u0050\u002a\u0025\u004a\u006c\u0033\u0034\u0056\u003e\u002e\u0067\u0063\u004c\u0049\u002c\u006c\u0038\u002f\u005d\u0043\u0050\u0057\u0024\u0046\u0070\u0023\u005a\u0061\u007d\u0075\u0030\u0031\u0037\u0066\u0037\u0049\u005f\u005d\u007d\u006f\u006c\u0034\u004a\u002b\u0063\u006c\u0043\u0025\u0047\u0051\u0048\u0044\u005a\u007b\u0030\u005d\u0064\u0058\u003d\u0041\u0068\u0021\u0027\u0057\u0044\u0060\u007c\u0056\u003f\u004d\u0025\u0027\u006f\u0050\u0022\u006e\u0054\u0036\u006c\u004e\u0026\u002c\u0048\u004a\u004d\u0031\u0056\u0055\u0074\u0050\u0021\u0040\u0024\u003c\u0047\u0023\u007a\u0045\u005e\u0052\u0061\u006a\u0037\u0064\u0039\u0067\u0061\u0036\u0064\u0051\u0040\u006f\u003e\u0056\u0044\u0061\u0034\u0066\u005b\u007d\u006c\u0032\u0078\u0072\u0033\u005f\u0050\u0035\u005d\u007e\u0048\u002c\u002c\u002f\u0079\u0061\u0028\u004e\u0031\u003f\u007c\u002a\u0049\u007a\u003f\u0076\u004d\u003d\u0054\u0068\u004c\u002f\u006d\u0063\u006e\u0064\u007b\u0070\u005a\u0036\u0060\u003d\u0055\u005d\u0072\u0077\u007d\u0065\u006a\u0071\u004d\u003e\u0023\u005a\u003d\u0040\u0057\u004b\u0070\u0037\u0048\u005b\u0033\u007b\u006b\u002d\u0022\u006c\u0070\u0072\u006b\u0060\u0072\u005b\u0021\u0063\u006d\u0056\u0076\u0046\u0027\u0067\u0070\u0031\u002c\u0060\u0033\u002f\u0074\u0055\u0048\u0036\u0031\u0054\u0076\u004e\u0069\u0034\u0061\u0057\u0041\u0072\u0035\u0043\u005e\u0041\u004e\u0059\u004c\u003e\u0048\u006b\u005e\u005c\u002a\u0069\u0035\u0037\u002c\u002d\u0058\u0037\u0021\u0023\u0052\u0054\u005f\u007d\u007b\u003b\u0053\u0022\u0038\u0040\u0042\u0060\u0048\u007e\u0033\u004b\u007e\u0053\u006d\u0031\u004e\u0022\u005a\u0028\u0052\u0020\u0033\u002a\u0041\u0061\u0072\u0023\u0078\u002d\u0037\u004e\u0043\u0039\u0024\u0040\u0061\u007c\u005f\u0042\u004a\u0056\u0067\u0028\u005c\u0025\u006f\u0023\u005f\u0031\u0029\u002d\u006e\u0060\u004a\u006d\u0062\u0073\u0072\u003c\u004a\u0062\u0056\u0048\u0053\u0070\u0063\u0070\u003e\u0023\u0055\u004e\u003a\u003c\u0029\u0030\u0038\u0065\u0054\u002e\u0057\u007c\u0078\u006e\u002e\u004f\u0074\u0023\u0067\u005e\u0055\u007e\u002c\u0027\u0078\u0028\u0072\u003e\u004e\u004e\u004f\u005c\u003c\u0058\u0076\u0048\u006b\u0071\u005e\u0079\u0076\u0074\u0029\u0031\u004a\u0075\u0068\u004e\u007d\u0029\u0079\u0074\u0025\u002d\u005c\u004b\u0048\u0072\u0030\u0043\u006c\u0053\u007c\u006f\u0049\u002a\u0077\u0049\u0069\u006f\u005c\u006b\u002f\u0027\u0064\u002e\u0034\u0046\u0050\u004b\u0033\u0065\u0057\u0065\u0023\u0037\u0059\u0025\u0029\u005e\u0071\u005e\u007c\u0032\u0069\u004a\u0046\u0070\u003c\u0061\u0051\u0029\u0025\u0024\u0079\u0054\u0055\u0045\u0074\u0044\u0055\u0031\u003f\u004f\u0046\u006c\u0024\u0044\u007e\u006c\u0032\u0065\u0049\u0052\u0040\u002e\u0068\u0051\u0043\u0038\u0022\u0056\u005a\u0041\u0057\u0024\u007b\u007d\u0042\u007b\u0027\u002c\u0061\u0040\u0040\u007d\u0053\u004a\u003e\u0035\u0073\u0070\u005c\u0053\u002c\u007a\u0056\u004d\u005c\u006f\u0071\u0067\u0076\u0026\u004f\u0068\u003a\u0029\u0067\u007b\u007c\u0067\u004c\u0030\u0067\u0024\u0079\u002b\u0048\u007e\u0072\u0025\u0055\u0040\u002c\u0051\u006a\u0039\u004e\u005e\u0021\u0063\u0020\u0022\u0031\u0072\u004b\u0045\u0077\u0047\u0069\u005d\u004f\u0068\u0033\u0020\u0065\u0020\u003a\u003a\u0063\u0038\u004c\u0077\u007a\u0052\u0067\u004d\u0050\u0038\u0058\u006b\u0024\u0041\u0079\u005e\u0051\u003b\u002d\u0027\u0029\u002e\u0066\u004a\u002b\u0045\u0046\u0057\u004b\u0061\u003b\u0060\u007a\u0061\u0045\u0047\u0054\u002f\u0059\u0053\u006b\u0063\u0045\u0056\u0045\u0079\u0053\u0020\u004c\u0064\u0067\u0045\u0049\u0072\u003d\u0073\u002a\u006f\u0039\u0024\u0067\u0046\u0024\u005e\u0030\u0051\u0020\u0040\u006e\u0039\u0054\u0066\u0026\u0052\u0025\u0030\u0033\u0041\u0045\u0071\u002c\u0052\u0062\u0064\u003e\u0044\u0067\u007c\u0047\u002f\u006c\u0040\u0035\u0023\u0069\u0063\u0049\u0021\u0043\u0064\u0049\u0026\u0045\u0074\u0042\u0062\u0030\u0020\u0023\u002a\u005b\u0021\u0022\u0045\u0040\u0060\u007d\u0048\u006c\u0032\u0074\u0074\u002e\u004f\u0025\u0035\u0033\u007a\u003d\u002f\u0033\u0040\u003c\u0042\u005f\u002c\u004f\u005e\u0073\u0025\u0073\u006c\u0022\u007b\u004b\u0035\u007c\u0026\u006e\u0078\u0054\u0079\u0058\u0025\u0077\u0022\u0022\u0079\u006a\u0032\u004a\u005c\u0078\u0067\u0023\u0021\u0041\u0060\u003c\u003f\u003c\u002b\u006a\u0026\u002c\u003d\u0026\u005c\u0044\u0064\u0032\u0059\u0021\u0029\u0029\u004b\u006a\u0025\u0030\u0073\u0026\u0074\u0077\u0021\u0035\u0048\u0022\u0026\u005a\u0022\u0044\u0078\u0051\u004f\u005d\u0024\u0026\u0020\u007a\u0020\u0068\u007e\u0040\u0062\u004f\u006e\u007e\u002b\u002a\u0032\u006f\u0078\u0048\u0061\u0033\u0061\u0034\u004a\u0024\u0076\u0060\u004d\u003b\u007e\u0057\u0024\u0060\u002c\u0079\u0050\u002e\u002d\u0053\u005a\u005d\u004f\u0049\u007c\u0035\u0050\u0046\u0041\u003b\u005c\u0050\u003f\u006c\u0044\u0060\u004f\u0069\u004b\u0044\u0043\u002f\u002b\u0022\u0064\u0075\u0037\u0054\u007e\u005f\u005f\u0043\u0048\u004a\u0072\u007d\u002a\u0023\u0070\u0050\u0053\u0065\u0075\u005f\u0032\u0066\u0072\u0044\u002c\u0021\u0020\u0029\u007d\u0057\u0042\u0058\u0044\u005e\u003d\u0042\u0059\u0067\u002c\u0039\u0022\u0075\u003f\u0060\u007e\u002a\u0079\u0068\u0073\u002d\u005e\u0020\u0054\u0060\u005d\u003b\u0048\u005e\u0047\u0037\u006c\u003c\u0046\u007c\u0058\u0023\u005f\u004e\u007e\u0074\u003b\u002c\u0034\u0056\u0059\u0063\u006d\u002f\u003c\u0061\u0078\u003b\u005e\u0049\u0035\u0074\u0025\u004b\u003e\u002a\u004c\u0073\u0046\u0022\u0054\u002b\u005c\u0063\u006e\u0072\u0061\u0034\u0060\u005a\u0054\u006f\u0058\u0046\u0037\u0037\u003b\u0053\u0029\u0076\u003d\u0031\u006d\u002c\u004c\u004e\u005e\u004a\u0070\u0038\u0060\u0064\u005b\u006e\u006f\u0043\u0075\u0063\u0042\u005e\u006e\u0063\u007d\u0078\u002a\u0022\u0079\u0078\u0067\u0063\u0074\u0046\u0053\u0064\u0066\u0042\u003c\u002a\u005e\u004e\u0047\u0039\u002a\u003f\u003c\u003b\u0036\u005d\u0077\u003d\u0027\u006e\u0076\u0031\u005c\u007c\u0072\u006c\u0074\u0055\u0058\u004a\u0053\u0073\u0077\u002f\u0025\u002c\u005a\u005b\u003e\u002c\u0076\u0034\u0078\u004c\u0071\u004c\u007b\u0020\u0073\u0023\u0072\u005d\u003c\u0069\u0079\u0048\u007b\u0050\u0051\u006f\u0037\u0026\u0072\u0074\u002f\u0037\u003f\u0063\u0024\u0022\u0071\u0059\u005c\u0028\u0044\u0020\u005d\u0055\u0079\u006c\u0068\u0076\u005b\u0035\u006f\u005a\u0070\u0026\u007a\u0074\u005f\u0036\u0025\u0067\u0022\u0027\u004d\u003d\u0052\u005f\u0042\u005d\u002c\u0037\u007a\u004d\u0059\u0058\u0027\u0039\u0071\u0024\u0076\u005d\u006e\u0027\u0060\u0050\u0045\u005c\u002a\u002e\u004d\u0042\u0037\u0030\u002d\u0043\u007a\u003e\u0021\u0062\u003c\u0048\u0067\u0040\u0050\u002a\u0042\u0062\u0050\u006d\u003c\u0073\u0056\u0048\u002c\u0047\u004e\u0078\u0025\u0053\u0066\u002f\u0048\u0047\u007c\u0063\u0065\u007c\u0066\u0070\u0036\u0056\u0050\u0070\u005e\u0077\u0062\u0050\u0065\u0024\u0074\u0029\u0064\u0046\u003f\u0041\u0066\u0048\u003b\u004b\u0032\u0026\u0049\u002a\u003f\u0077\u007b\u0037\u0058\u0056\u005b\u006a\u003e\u0034\u0039\u0031\u002c\u007a\u0021\u0058\u002b\u002e\u0072\u002c\u005d\u0056\u0033\u0030\u0021\u0073\u006c\u002c\u0039\u0048\u0079\u0061\u0035\u0078\u0032\u003a\u003b\u0071\u0032\u0026\u0075\u0032\u007e\u0065\u0073\u0049\u0028\u002e\u0038\u0067\u0024\u0036\u0062\u003b\u006c\u002f\u003a\u0025\u0032\u0032\u006c\u0060\u002c\u0069\u0048\u004a\u003b\u004b\u0055\u0049\u0020\u0063\u0072\u004d\u002a\u0042\u004a\u0041\u0031\u0037\u0020\u006c\u003a\u006c\u002f\u004b\u0062\u0062\u003b\u007b\u0033\u002c\u002a\u0030\u003c\u007a\u0051\u0054\u0051\u004a\u007b\u0060\u0051\u005f